function update(dt) {
    // Simple horizontal movement based on arrow keys or A/D
    const accel = 400; // px/sec^2
    const maxSpeed = 300; // px/sec
    const friction = 300; // deceleration when no input
    let ax = 0;
    if (keys.has('ArrowLeft') || keys.has('a') || keys.has('A')) ax -= accel;
    if (keys.has('ArrowRight') || keys.has('d') || keys.has('D')) ax += accel;
    // Apply acceleration to velocity
    player.vx += ax * dt;
    // Apply friction when no horizontal input
    if (!keys.has('ArrowLeft') && !keys.has('a') && !keys.has('A') && !keys.has('ArrowRight') && !keys.has('d') && !keys.has('D')) {
      if (player.vx > 0) {
        player.vx = Math.max(0, player.vx - friction * dt);
      } else if (player.vx < 0) {
        player.vx = Math.min(0, player.vx + friction * dt);
      }
    }
    // Clamp speed
    player.vx = Math.max(-maxSpeed, Math.min(maxSpeed, player.vx));
    // Update position
    player.x += player.vx * dt;
    // Keep player within canvas bounds
    const canvas = document.getElementById('game');
    if (player.x < player.radius) player.x = player.radius;
    if (player.x > canvas.width - player.radius) player.x = canvas.width - player.radius;
  }

